import{_ as o,C as n,o as i,c as s,aj as e,G as r}from"./chunks/framework.BwH0p-pt.js";const m=JSON.parse('{"title":"Product Variants","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/products/variants.md","filePath":"3.0/products/variants.md","lastUpdated":1788942616000}'),l={name:"3.0/products/variants.md"};function d(c,t,h,u,p,g){const a=n("ImagePopup");return i(),s("div",null,[t[0]||(t[0]=e('<h1 id="product-variants" tabindex="-1">Product Variants <a class="header-anchor" href="#product-variants" aria-label="Permalink to &quot;Product Variants&quot;">​</a></h1><p>Many products exist in more than one version — a jacket in several colours and sizes, a phone in several storage capacities. <strong>Product Variants</strong> in UnoPim 3.0 let you manage all of those versions under one parent product: you enrich the shared information <strong>once</strong> on the parent, and every variant inherits it automatically. Your team only fills in what actually differs — like the SKU, the size, or a colour-specific photo.</p><p>This page explains how variants are structured, how to set up a variant structure on an attribute family, and how to create and enrich variants from the product page.</p><h2 id="how-variants-are-organized" tabindex="-1">How variants are organized <a class="header-anchor" href="#how-variants-are-organized" aria-label="Permalink to &quot;How variants are organized&quot;">​</a></h2><p>A variant catalog has up to three layers:</p><table tabindex="0"><thead><tr><th>Layer</th><th>What it holds</th><th>Example (fashion)</th></tr></thead><tbody><tr><td><strong>Parent product</strong></td><td>Values maintained once and inherited by every variant — name, description, brand, care instructions.</td><td>The &quot;Classic Denim Jacket&quot; style.</td></tr><tr><td><strong>Variant group</strong> <em>(two-level structures only)</em></td><td>Values shared by all variants inside one group — for example a photo shared by every size of the same colour.</td><td>The &quot;Blue&quot; version of the jacket.</td></tr><tr><td><strong>Variant</strong></td><td>Values maintained separately for each final, sellable product — SKU, size, price, stock-level data.</td><td>Blue jacket, size M.</td></tr></tbody></table><p>The attributes that split a product into variants are called <strong>axes</strong>. An axis is a select-type attribute such as <code>color</code> or <code>size</code>. A one-level structure has one set of axes (Parent → Variant); a two-level structure has axes on each level (Parent → Variant group → Variant).</p>',7)),r(a,{src:"/assets/3.0/images/products/variant-structure.png",alt:"Variant structure editor showing parent, sub-parent, and variant levels"}),t[1]||(t[1]=e('<h2 id="one-level-or-two" tabindex="-1">One level or two? <a class="header-anchor" href="#one-level-or-two" aria-label="Permalink to &quot;One level or two?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Choose</th><th>When</th><th>Examples</th></tr></thead><tbody><tr><td><strong>1 level · Parent → Variant</strong></td><td>Products vary along a single dimension, or the combinations are few and nothing is shared per option.</td><td>A notebook in 4 colours; a cable in 3 lengths.</td></tr><tr><td><strong>2 levels · Parent → Sub-parent → Variant</strong></td><td>Products vary along two dimensions <strong>and</strong> the first dimension carries its own shared data — like a colour-specific image or colour name.</td><td>Fashion: style → colour → size. Electronics: model → colour → storage capacity.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you are unsure, start with one level. Two levels earn their keep when the middle layer genuinely shares data — enriching a photo once per colour instead of once per size is where the time savings come from.</p></div><h2 id="set-up-a-variant-structure-on-the-family" tabindex="-1">Set up a variant structure on the family <a class="header-anchor" href="#set-up-a-variant-structure-on-the-family" aria-label="Permalink to &quot;Set up a variant structure on the family&quot;">​</a></h2><p>Variant structures belong to the <strong>attribute family</strong>, so every product in the family splits into variants the same way.</p><ol><li>Go to <strong>Catalog → Attribute Families</strong> and open the family.</li><li>Open the <strong>Variants</strong> tab.</li><li>Click <strong>Add Variant</strong> to create a variant structure. Give it a name (for example <em>Color + Size</em>).</li><li>Choose the structure: <strong>Parent → Child</strong> (one level) or <strong>Parent → Sub-parent → Child</strong> (two levels).</li><li>Pick the <strong>axis</strong> attribute for each level — for example <code>color</code> for level 1 and <code>size</code> for level 2. Axes must be select attributes without channel or locale scope.</li><li>Decide where each remaining attribute is maintained. Every attribute is <strong>common</strong> (parent level) by default; drag only the ones that differ into the level that owns them — for example the image to the sub-parent level, and price and EAN to the variant level.</li><li>Save the structure.</li></ol>',6)),r(a,{src:"/assets/3.0/images/products/variant-family-setup.png",alt:"Assigning attributes to variant levels on the attribute family"}),t[2]||(t[2]=e('<p>A family can hold several variant structures — one per way its products vary. You choose which structure a product uses when you create it.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Once products use a variant structure, its axes and levels are <strong>locked</strong>. You can no longer change them without deleting the existing variants first, so plan the axes before your team starts creating products.</p></div><h2 id="create-a-product-with-variants" tabindex="-1">Create a product with variants <a class="header-anchor" href="#create-a-product-with-variants" aria-label="Permalink to &quot;Create a product with variants&quot;">​</a></h2><ol><li>Go to <strong>Catalog → Products</strong> and click <strong>Create Product</strong>.</li><li>In the <strong>Create New Product</strong> dialog, set <strong>Type</strong> to <code>Configurable</code>, pick the <strong>Family</strong>, enter the parent <strong>SKU</strong>, and click <strong>Next</strong>.</li><li>Select the <strong>Variant Structure</strong> the product should use and click <strong>Save Product</strong>.</li></ol><p>UnoPim opens the product edit page. Fill in the shared values here — name, description, categories, brand. Everything you enter on the parent is inherited by every variant you add later.</p><h2 id="add-variants-from-the-product-page" tabindex="-1">Add variants from the product page <a class="header-anchor" href="#add-variants-from-the-product-page" aria-label="Permalink to &quot;Add variants from the product page&quot;">​</a></h2><p>On the parent product&#39;s edit page, open the <strong>Variations</strong> section:</p><ol><li>Click <strong>Add New</strong> and pick (or create) the first-axis option — for example the colour <code>Blue</code>.</li><li>In a two-level structure, UnoPim creates the <strong>variant group</strong> for that option automatically. Select the group, then add the final variants inside it — one per second-axis option (for example each size).</li><li>For each variant, enter its <strong>SKU</strong> and pick the axis value, then click <strong>Create</strong>.</li><li>Open any variant to fill in its own values — the ones your structure assigns to the variant level, such as price or stock data.</li></ol><p>The Variations panel shows a completeness counter per group (for example <em>3 of 5 complete</em>), so you can see at a glance which variants still need enrichment.</p>',9)),r(a,{src:"/assets/3.0/images/products/variant-variations-panel.png",alt:"Variations section on the product edit page with variant groups and completeness counts"}),t[3]||(t[3]=e('<h2 id="inherited-values-in-the-editor" tabindex="-1">Inherited values in the editor <a class="header-anchor" href="#inherited-values-in-the-editor" aria-label="Permalink to &quot;Inherited values in the editor&quot;">​</a></h2><p>When you open a variant, inherited fields are shown but not editable at that level. A hint tells you where the value lives — for example <em>&quot;This attribute can be updated in the common attributes&quot;</em>. To change an inherited value, edit it once on the parent (or on the variant group), and the change flows down to every product that inherits it.</p><p>This keeps your data consistent by design: a corrected description or an updated brand name never has to be repeated across dozens of size/colour combinations.</p><h2 id="related-reading" tabindex="-1">Related reading <a class="header-anchor" href="#related-reading" aria-label="Permalink to &quot;Related reading&quot;">​</a></h2><ul><li><strong><a href="./configurable.html">Configurable Product</a></strong> — the step-by-step guide to creating a configurable product.</li><li><strong><a href="./../attribute/attribute-family.html">Attribute Family</a></strong> — where variant structures are defined.</li><li><strong><a href="./filters-and-views.html">Filters &amp; Saved Views</a></strong> — find and slice variant catalogs in the product grid.</li></ul>',5))])}const f=o(l,[["render",d]]);export{m as __pageData,f as default};
